INSERT INTO `quizzes` VALUES (1,'DSA Quiz 1: Arrays, Linked Lists & Complexity','Covers Big-O notation, contiguous vs linked allocation, singly/doubly/circular linked lists.',70,'2026-10-30 20:21:54',30),(2,'DSA Quiz 2: Stacks, Queues & Recursion','Covers LIFO/FIFO operations, infix-to-postfix conversion, circular queues, priority queues, and call stacks.',70,'2026-10-30 20:21:54',30),(3,'DSA Quiz 3: Trees, Binary Search Trees & Heaps','Covers tree traversals, BST insertion/deletion, AVL rotations, and binary min/max heaps.',70,'2026-10-30 20:21:54',30),(4,'DSA Quiz 4: Graphs, Traversals & Shortest Paths','Covers adjacency matrices/lists, BFS, DFS, Dijkstra, Bellman-Ford, Prim, and Kruskal algorithms.',70,'2026-10-30 20:21:54',30),(5,'DSA Quiz 5: Sorting, Searching & Dynamic Programming','Covers QuickSort, MergeSort, HeapSort, hashing collision resolution, and memoization/tabulation.',70,'2026-10-30 20:21:54',30),(6,'DBMS Quiz 1: Relational Model & ER Diagrams','Covers entities, attributes, cardinalities, keys (super, candidate, primary, foreign), and relational algebra.',71,'2026-10-30 20:21:54',30),(7,'DBMS Quiz 2: SQL Queries, Joins & Aggregations','Covers DDL, DML, INNER/OUTER joins, GROUP BY, HAVING, subqueries, and views.',71,'2026-10-30 20:21:54',30),(8,'DBMS Quiz 3: Normalization & Functional Dependencies','Covers Armstrong\'s axioms, closure, 1NF, 2NF, 3NF, BCNF, and lossless join decomposition.',71,'2026-10-30 20:21:54',30),(9,'DBMS Quiz 4: Transactions, Concurrency & Recovery','Covers ACID properties, serializability, two-phase locking (2PL), deadlocks, and log-based recovery.',71,'2026-10-30 20:21:54',30),(10,'DBMS Quiz 5: Indexing, B-Trees & Query Optimization','Covers clustered/non-clustered indexes, B-Trees, B+ Trees, hashing, and cost-based query optimization.',71,'2026-10-30 20:21:54',30),(11,'OS Quiz 1: Architecture, System Calls & Processes','Covers kernel modes, system calls, PCB, process states, context switching, and fork/exec.',72,'2026-10-30 20:21:54',30),(12,'OS Quiz 2: CPU Scheduling & Multithreading','Covers FCFS, SJF, SRTF, Round Robin, Priority scheduling, and user vs kernel threads.',72,'2026-10-30 20:21:54',30),(13,'OS Quiz 3: Process Synchronization & Deadlocks','Covers critical section problem, mutexes, semaphores, monitors, and Banker\'s algorithm.',72,'2026-10-30 20:21:54',30),(14,'OS Quiz 4: Memory Management, Paging & Segmentation','Covers contiguous allocation, paging, TLB, page replacement (FIFO, LRU, Optimal), and thrashing.',72,'2026-10-30 20:21:54',30),(15,'OS Quiz 5: File Systems, Disk Scheduling & I/O','Covers inode structures, directory allocation, SCAN/C-SCAN/SSTF disk scheduling, and RAID.',72,'2026-10-30 20:21:54',30),(16,'CN Quiz 1: OSI & TCP/IP Models and Physical Layer','Covers layered architecture, encapsulation, transmission media, multiplexing, and switching.',73,'2026-10-30 20:21:54',30),(17,'CN Quiz 2: Data Link Layer, Framing & MAC Protocols','Covers CRC, Hamming code, Stop-and-Wait, Go-Back-N, Selective Repeat, CSMA/CD, and Ethernet.',73,'2026-10-30 20:21:54',30),(18,'CN Quiz 3: Network Layer, IPv4/IPv6 & Routing','Covers subnetting, CIDR, ARP, ICMP, Distance Vector (RIP), and Link State (OSPF) routing.',73,'2026-10-30 20:21:54',30),(19,'CN Quiz 4: Transport Layer, TCP, UDP & Congestion','Covers port numbers, 3-way handshake, flow control, slow start, congestion avoidance, and UDP.',73,'2026-10-30 20:21:54',30),(20,'CN Quiz 5: Application Layer, DNS, HTTP & Security','Covers DNS resolution, HTTP/HTTPS methods and status codes, SMTP, FTP, firewalls, and TLS.',73,'2026-10-30 20:21:54',30),(21,'Java Quiz 1: Fundamentals, Data Types & Control Flow','Covers JVM/JRE/JDK architecture, primitive types, operators, arrays, and String immutability.',74,'2026-10-30 20:21:54',30),(22,'Java Quiz 2: Classes, Objects, Inheritance & Polymorphism','Covers constructors, this/super keywords, method overloading vs overriding, and dynamic dispatch.',74,'2026-10-30 20:21:54',30),(23,'Java Quiz 3: Interfaces, Abstract Classes & Packages','Covers abstraction, multiple interface implementation, access modifiers, and package visibility.',74,'2026-10-30 20:21:54',30),(24,'Java Quiz 4: Exception Handling & Multithreading','Covers checked vs unchecked exceptions, try-catch-finally, Thread lifecycle, and synchronized blocks.',74,'2026-10-30 20:21:54',30),(25,'Java Quiz 5: Collections Framework, Generics & Streams','Covers ArrayList, HashMap, HashSet, Comparable vs Comparator, generics wildcards, and Stream API.',74,'2026-10-30 20:21:54',30),(26,'Python Quiz 1: Basics, Variables, Operators & Flow','Covers dynamic typing, truthiness, loops, slicing, string formatting, and operator precedence.',75,'2026-10-30 20:21:54',30),(27,'Python Quiz 2: Lists, Tuples, Sets & Dictionaries','Covers mutability, list comprehensions, dictionary hashing, set operations, and unpacking.',75,'2026-10-30 20:21:54',30),(28,'Python Quiz 3: Functions, Lambdas, Modules & File I/O','Covers *args/**kwargs, closures, lambda expressions, context managers (with), and JSON/CSV handling.',75,'2026-10-30 20:21:54',30),(29,'Python Quiz 4: OOP & Exception Handling in Python','Covers dunder methods (__init__, __str__), MRO, @classmethod/@staticmethod, and custom exceptions.',75,'2026-10-30 20:21:54',30),(30,'Python Quiz 5: Iterators, Generators, Decorators & Regex','Covers yield, generator expressions, function decorators, functools, and the re module.',75,'2026-10-30 20:21:54',30),(31,'SE Quiz 1: SDLC & Agile Development Models','Covers Waterfall, Spiral, Incremental, Prototyping, Scrum roles/ceremonies, and Kanban.',76,'2026-10-30 20:21:54',30),(32,'SE Quiz 2: Requirements Engineering & System Modeling','Covers functional vs non-functional requirements, SRS, UML use case, sequence, and class diagrams.',76,'2026-10-30 20:21:54',30),(33,'SE Quiz 3: Architecture, Coupling, Cohesion & Patterns','Covers layered/microservices architecture, low coupling, high cohesion, and GoF design patterns.',76,'2026-10-30 20:21:54',30),(34,'SE Quiz 4: Software Testing, Verification & Validation','Covers unit, integration, system, acceptance, black-box (BVA/ECP), white-box (cyclomatic complexity).',76,'2026-10-30 20:21:54',30),(35,'SE Quiz 5: Project Management, Estimation & Maintenance','Covers COCOMO, Function Point Analysis, risk management, Git version control, and Lehman\'s laws.',76,'2026-10-30 20:21:54',30),(36,'Web Quiz 1: HTML5 Semantic Elements, Forms & Standards','Covers DOM tree structure, semantic tags, form validation attributes, audio/video, and accessibility.',77,'2026-10-30 20:21:54',30),(37,'Web Quiz 2: CSS3 Selectors, Flexbox, Grid & Responsive','Covers box model, specificity, Flexbox axes, CSS Grid templates, and media queries.',77,'2026-10-30 20:21:54',30),(38,'Web Quiz 3: JavaScript ES6, DOM & Async Programming','Covers let/const, arrow functions, event delegation, Promises, async/await, and Fetch API.',77,'2026-10-30 20:21:54',30),(39,'Web Quiz 4: Backend Routing, REST APIs & Sessions','Covers HTTP methods (GET, POST, PUT, DELETE), cookies, sessions, JWT, and template rendering.',77,'2026-10-30 20:21:54',30),(40,'Web Quiz 5: Web Security, CORS, Auth & Performance','Covers XSS, CSRF, SQL injection prevention, password hashing, CORS headers, and caching.',77,'2026-10-30 20:21:54',30),(41,'AI/ML Quiz 1: Uninformed & Informed Search Algorithms','Covers BFS, DFS, Uniform Cost Search, A* admissibility/consistency, and Minimax with alpha-beta pruning.',78,'2026-10-30 20:21:54',30),(42,'AI/ML Quiz 2: Knowledge Representation & Logic','Covers propositional logic, first-order predicate logic, resolution refutation, and Bayesian networks.',78,'2026-10-30 20:21:54',30),(43,'AI/ML Quiz 3: Supervised Learning: Regression & Classification','Covers linear/logistic regression, decision trees, SVM, k-NN, gradient descent, and regularization.',78,'2026-10-30 20:21:54',30),(44,'AI/ML Quiz 4: Unsupervised Learning & Dimensionality Reduction','Covers K-Means, hierarchical clustering, DBSCAN, PCA eigenvectors, and curse of dimensionality.',78,'2026-10-30 20:21:54',30),(45,'AI/ML Quiz 5: Neural Networks, Deep Learning & Evaluation','Covers perceptrons, activation functions (ReLU, Sigmoid), backpropagation, precision/recall/F1, and ROC-AUC.',78,'2026-10-30 20:21:54',30),(46,'COA Quiz 1: Number Systems, Boolean Algebra & Logic','Covers 2\'s complement, IEEE 754 floating point, De Morgan\'s laws, K-maps, and multiplexers/decoders.',79,'2026-10-30 20:21:54',30),(47,'COA Quiz 2: ISA, Addressing Modes & Registers','Covers RISC vs CISC, immediate/direct/indirect/indexed addressing, instruction formats, and program counter.',79,'2026-10-30 20:21:54',30),(48,'COA Quiz 3: ALU Design, Arithmetic & Control Unit','Covers carry-lookahead adder, Booth\'s multiplication, hardwired vs microprogrammed control units.',79,'2026-10-30 20:21:54',30),(49,'COA Quiz 4: Instruction Pipelining & Hazard Resolution','Covers 5-stage RISC pipeline, structural/data/control hazards, forwarding, stalling, and branch prediction.',79,'2026-10-30 20:21:54',30),(50,'COA Quiz 5: Memory Hierarchy, Cache Mapping & I/O','Covers direct, associative, set-associative cache, write-through vs write-back, interrupts, and DMA.',79,'2026-10-30 20:21:54',30);
