INSERT INTO `review_submissions` VALUES (1,2,'Clarification on AVL Tree Rotation Question in DSA Quiz 3','In Question 25 of DSA Quiz 3, both single and double rotation options seemed applicable for the LR case. Kindly review my response.','approved','2026-10-12 20:38:16'),(2,4,'Network Interruption During DBMS Quiz 2','My Wi-Fi disconnected briefly during the last 3 minutes of DBMS Quiz 2 (SQL Joins). Requesting verification of my submitted score.','approved','2026-10-14 20:38:16'),(3,6,'Ambiguity in OS Quiz 3 Banker\'s Algorithm Options','In OS Quiz 3 Question 5, option A and option B had similar wording regarding safe sequence verification.','pending','2026-10-25 20:38:16'),(4,9,'Score Recalculation Request for CN Quiz 3 Subnetting','I selected /26 (255.255.255.192) for 62 usable hosts in CN Quiz 3, please verify if it was recorded properly.','approved','2026-10-18 20:38:16'),(5,12,'Java Quiz 5 HashMap Collision Tree Threshold','Requesting review on Java Quiz 5 Question 9 regarding bucket-to-Red-Black-Tree conversion in JDK 8+.','approved','2026-10-20 20:38:16'),(6,15,'Python Quiz 2 Mutable Default Argument Question','Submitted Python Quiz 2 on time; requesting feedback on Question 8 regarding default list evaluation.','rejected','2026-10-16 20:38:16'),(7,18,'Extra Attempt Request for SE Quiz 4 Cyclomatic Complexity','Browser tab accidentally closed during SE Quiz 4 after completing 20 out of 25 questions.','pending','2026-10-27 20:38:16'),(8,21,'Web Quiz 3 Promise Microtask Queue Order','Please review my explanation for the Event Loop microtask vs macrotask execution order in Web Quiz 3.','approved','2026-10-21 20:38:16'),(9,23,'AI/ML Quiz 1 A* Heuristic Admissibility Question','In AI/ML Quiz 1, I wanted to confirm the distinction between admissibility in trees vs consistency in graphs.','approved','2026-10-23 20:38:16'),(10,26,'COA Quiz 4 Pipeline Hazard Forwarding Question','Requesting a review on the load-use data hazard stall question in COA Quiz 4.','pending','2026-10-28 20:38:16'),(11,30,'DBMS Quiz 4 Serializable Isolation Level','Completed DBMS Quiz 4 with 22/25; requesting review of Question 25 on phantom reads.','approved','2026-10-19 20:38:16'),(12,34,'OS Quiz 4 Belady\'s Anomaly FIFO Frame Count','Please check Question 7 in OS Quiz 4 regarding FIFO page fault increase when frames increase from 3 to 4.','approved','2026-10-22 20:38:16'),(13,37,'CN Quiz 4 TCP Slow Start ssthresh Calculation','In CN Quiz 4, please verify the congestion window doubling calculation on Question 19.','pending','2026-10-29 20:38:16'),(14,41,'Java Quiz 4 Checked vs Unchecked Exception Hierarchy','Requesting review of my answer on RuntimeException vs IOException in Java Quiz 4.','rejected','2026-10-15 20:38:16'),(15,45,'Python Quiz 5 Generator yield State Preservation','Completed Python Quiz 5; requesting confirmation that my last 2 answers were saved before timeout.','approved','2026-10-24 20:38:16'),(16,49,'SE Quiz 2 Functional vs Non-Functional SRS Item','In SE Quiz 2, response time under 200ms was marked during my attempt; requesting review.','pending','2026-10-26 20:38:16'),(17,53,'Web Quiz 5 CSRF SameSite Cookie Attribute','Please review Question 15 in Web Quiz 5 regarding CSRF tokens and SameSite cookie protection.','approved','2026-10-17 20:38:16'),(18,57,'AI/ML Quiz 3 L1 Lasso Sparsity vs L2 Ridge','Requesting feedback on my AI/ML Quiz 3 attempt regarding feature selection via L1 penalty.','approved','2026-10-25 20:38:16'),(19,61,'COA Quiz 5 Effective Memory Access Time Formula','In COA Quiz 5 Question 18, I calculated EMAT = Hit Time + Miss Rate * Miss Penalty. Please verify.','pending','2026-10-29 20:38:16'),(20,64,'DSA Quiz 4 Dijkstra Priority Queue Complexity','Requesting review of Question 16 in DSA Quiz 4 for binary heap time complexity O((V+E) log V).','approved','2026-10-26 20:38:16');
/*!40000 ALTER TABLE `review_submissions` ENABLE KEYS */;
